"""Seed-0 CPU RNG state after constructing/loading the released DA3-small wrapper.

The upstream wrapper briefly constructs native heads and removes them. Restoring this
state preserves the exact random initialization of the retained DPT and voxel heads
without vendoring those unused modules.
"""
import base64
import torch

_STATE_B64 = ""


def restore_reference_head_rng_state() -> None:
    raw = base64.b64decode(_STATE_B64)
    torch.set_rng_state(torch.tensor(list(raw), dtype=torch.uint8))
